import type { Limiter } from './limiter';

/**
 * Everything the Worker reads from its environment. Hand-written (rather than
 * generated by `wrangler types`) because secrets are never in wrangler.jsonc
 * and a generated file would differ between machines that do and do not have a
 * local `.dev.vars`.
 */
export interface Env {
  // Public vars (wrangler.jsonc)
  ALLOWED_ORIGINS: string;
  MODEL: string;
  DAILY_LLM_CAP: string;
  LEAD_TO_EMAIL: string;
  LEAD_FROM_EMAIL: string;
  RATE_SALT: string;
  /** "anthropic" in production, "mock" for local runs and tests. */
  LLM_PROVIDER: string;

  // Durable Object binding
  LIMITER: DurableObjectNamespace<Limiter>;

  // Secrets (`npx wrangler secret put <NAME>`), all optional at runtime
  LLM_API_KEY?: string;
  RESEND_API_KEY?: string;
  TURNSTILE_SECRET_KEY?: string;
  LEADQUIK_WEBHOOK_URL?: string;
}

// Make `import { env } from 'cloudflare:workers'` carry the same type.
type WorkerEnv = Env;
declare global {
  namespace Cloudflare {
    interface Env extends WorkerEnv {}
  }
}

export type LlmStatus = 'anthropic' | 'mock' | 'unconfigured';

/**
 * Secrets are trimmed here, once, and every caller uses the trimmed value. A key pasted
 * with a trailing newline would otherwise pass an "is it set?" check and then be sent
 * with the whitespace attached.
 */
const trimmed = (value: string | undefined): string | undefined => {
  const clean = typeof value === 'string' ? value.trim() : '';
  return clean.length > 0 ? clean : undefined;
};

export const llmApiKey = (env: Env): string | undefined => trimmed(env.LLM_API_KEY);
export const resendApiKey = (env: Env): string | undefined => trimmed(env.RESEND_API_KEY);
export const turnstileSecret = (env: Env): string | undefined => trimmed(env.TURNSTILE_SECRET_KEY);
export const leadquikUrl = (env: Env): string | undefined => trimmed(env.LEADQUIK_WEBHOOK_URL);

export const isMockProvider = (env: Env): boolean =>
  env.LLM_PROVIDER?.trim().toLowerCase() === 'mock';

/** True when `/chat` can produce a reply (mock needs nothing, anthropic needs a key). */
export const isLlmConfigured = (env: Env): boolean => isMockProvider(env) || llmApiKey(env) !== undefined;

export const llmStatus = (env: Env): LlmStatus => {
  if (isMockProvider(env)) return 'mock';
  return llmApiKey(env) !== undefined ? 'anthropic' : 'unconfigured';
};

export const isEmailConfigured = (env: Env): boolean => resendApiKey(env) !== undefined;

export const isTurnstileConfigured = (env: Env): boolean => turnstileSecret(env) !== undefined;

export const allowedOrigins = (env: Env): string[] =>
  (env.ALLOWED_ORIGINS ?? '')
    .split(',')
    .map((origin) => origin.trim())
    .filter((origin) => origin.length > 0);

/**
 * `DAILY_LLM_CAP` as a whole number of model calls per Eastern-time day. 0 is valid and
 * switches the model off; missing, blank, non-numeric or negative values fall back to 2000.
 */
export const dailyLlmCap = (env: Env): number => {
  const parsed = Number.parseInt(env.DAILY_LLM_CAP ?? '', 10);
  return Number.isFinite(parsed) && parsed >= 0 ? parsed : 2000;
};
